#!/usr/bin/env python3
"""Type-II chamber, divisibility, and isotropic-ray gate for Delta_5.

This verifier checks target-side BKM lattice arithmetic:

* type-II simple reflections are generated by the three delta_i;
* the distinct type-II Coxeter pairs have no finite braid relation;
* type-I chamber automorphisms permute the three type-II walls and fix rho;
* type-I square-two roots have ambient divisibility one and are absent from
  the Delta_5 Humbert divisor packet;
* type-II square-two roots have ambient divisibility two and order one in the
  Delta_5 Humbert divisor packet;
* the primitive isotropic boundary rays a_ij=delta_i+delta_j are isotropic;
* their signed multiplicity is 10 and decomposes as 1+9;
* the Gritsenko--Nikulin isotropic directions u_{ij,r} give nine directions
  on each primitive isotropic ray.

It does not construct compact source representatives, Pfaffian orientations,
O2 wall atlases, mirror discriminants, protected traces, or a parity
decomposition of the target BKM root spaces.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
import sys
from collections import Counter
from dataclasses import dataclass
from fractions import Fraction
